import{_ as o,C as s,o as r,c,a6 as t,E as a}from"./chunks/framework.BgIEWZ8W.js";const f=JSON.parse('{"title":"JWT Attacks · Case File 08","description":"Dissect JSON Web Token verification flaws, signature forgery, alg none bypasses, jwk/jku header injection, and algorithm confusion.","frontmatter":{"title":"JWT Attacks · Case File 08","description":"Dissect JSON Web Token verification flaws, signature forgery, alg none bypasses, jwk/jku header injection, and algorithm confusion."},"headers":[],"relativePath":"jwt/index.md","filePath":"jwt/index.md"}'),d={name:"jwt/index.md"};function l(p,e,h,u,g,m){const i=s("LabGroup"),n=s("TopicComplete");return r(),c("div",null,[e[0]||(e[0]=t('<h1 id="jwt-attacks-·-forging-the-cryptographic-passport" tabindex="-1">JWT Attacks · Forging the Cryptographic Passport <a class="header-anchor" href="#jwt-attacks-·-forging-the-cryptographic-passport" aria-label="Permalink to &quot;JWT Attacks · Forging the Cryptographic Passport&quot;">​</a></h1><p class="wd-section-lede">A JSON Web Token (JWT) looks like a futuristic cryptographic seal, but under the hood, it is simply three Base64URL-encoded text blocks glued together with periods. The token is only as trustworthy as the server&#39;s verification routine. When an application lets the token&#39;s header tell it <em>how</em> to verify itself, the client gains control of the identity check.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Self-Inspected Diplomatic Passport.</strong> Imagine arriving at international passport control with a homemade passport booklet. On the first page, under <em>&quot;Verification Instructions&quot;</em>, you write: <code>Verification Protocol: None Required. Admit bearer immediately as Royal Ambassador</code>. If the border control agent blindly reads your note and waves you through without checking their own databases or consular seals, they committed the classic <code>alg: none</code> blunder: trusting the document to dictate its own verification rules.</p></div><h2 id="case-file-8-following-the-token-verification-behind-the-scenes" tabindex="-1">Case File #8: Following the Token Verification Behind the Scenes <a class="header-anchor" href="#case-file-8-following-the-token-verification-behind-the-scenes" aria-label="Permalink to &quot;Case File #8: Following the Token Verification Behind the Scenes&quot;">​</a></h2><p>Let&#39;s examine what happens when a browser sends an authenticated request using a JSON Web Token:</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You log into a website as user <code>wiener</code>. In your browser&#39;s Storage inspector, you find a session cookie containing a three-part string separated by dots: <code>eyJhbGciOi...eyJzdWIi...ABC123xyz</code>.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The server splits the token by periods into three components: Header, Payload, and Signature. It decodes the JSON payload to identify who is making the request:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Header (Algorithm declaration)</span><span><span class="wd-code-input">Gold</span> = Payload (User Claims)</span><span><span class="wd-code-dead">Strikethrough</span> = Cryptographic Signature</span></div><span class="wd-code-dev">eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9</span>.<span class="wd-code-input">eyJzdWIiOiJ3aWVuZXIiLCJhZG1pbiI6ZmFsc2V9</span>.<span class="wd-code-dead">SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>Many JWT verification implementations inspect the token&#39;s <code>alg</code> header claim to decide how to verify the signature. If the server supports the unsecured <code>&quot;alg&quot;: &quot;none&quot;</code> algorithm, or if the developers decoded the payload without calling the cryptographic verification function, an investigator can change <code>&quot;admin&quot;: false</code> to <code>&quot;admin&quot;: true</code>, strip the signature, and the server accepts the forged identity!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Never let the token&#39;s header choose the verification algorithm. Hardcode the expected algorithm on the server (e.g. strictly enforce RS256), explicitly reject tokens using <code>none</code>, look up signing keys from an internal key store rather than client headers, and always verify signatures before reading payload claims.</p></div></div><h3 id="visual-comparison-trusted-signature-vs-self-declared-verification" tabindex="-1">Visual Comparison: Trusted Signature vs. Self-Declared Verification <a class="header-anchor" href="#visual-comparison-trusted-signature-vs-self-declared-verification" aria-label="Permalink to &quot;Visual Comparison: Trusted Signature vs. Self-Declared Verification&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>Because the token is cryptographically signed with a secret key, any unauthorized modification to the username or admin claim will invalidate the signature and be rejected by the server.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>The backend verification function blindly trusts the algorithm in the token header, accepts weak secrets crackable in seconds, or accepts public keys supplied by the user in the header itself.</p></div></div><h3 id="the-5-checkpoints-of-jwt-verification" tabindex="-1">The 5 Checkpoints of JWT Verification <a class="header-anchor" href="#the-5-checkpoints-of-jwt-verification" aria-label="Permalink to &quot;The 5 Checkpoints of JWT Verification&quot;">​</a></h3><p>When validating an incoming bearer token, a robust security routine follows strict server-side rules:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Structure Check</strong> Verify token has three Base64URL parts separated by periods. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. Algorithm Pinning</strong> Enforce server-configured algorithm; reject <code>alg: none</code>. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Key Retrieval</strong> Fetch trusted key from internal store; ignore untrusted headers. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>4. Signature Check</strong> Verify cryptographic hash matches <code>header.payload</code> bytes. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Claims Validation</strong> Verify expiration (<code>exp</code>), audience (<code>aud</code>), and issuer (<code>iss</code>). </div></div><hr><h2 id="anatomy-of-a-token-unverified-signatures" tabindex="-1">Anatomy of a Token &amp; Unverified Signatures <a class="header-anchor" href="#anatomy-of-a-token-unverified-signatures" aria-label="Permalink to &quot;Anatomy of a Token &amp; Unverified Signatures&quot;">​</a></h2><p>A JWT consists of three distinct segments:</p><ol><li><strong>Header:</strong> Contains metadata, typically defining the token type (<code>typ: &quot;JWT&quot;</code>) and the cryptographic algorithm (<code>alg: &quot;HS256&quot;</code> or <code>&quot;RS256&quot;</code>).</li><li><strong>Payload:</strong> Contains user claims (<code>sub: &quot;123&quot;</code>, <code>role: &quot;admin&quot;</code>, <code>exp: 1710000000</code>). It is merely Base64URL-encoded, not encrypted—anyone can read its contents!</li><li><strong>Signature:</strong> Generated by computing a cryptographic signature over the combined string <code>Base64URL(Header) + &quot;.&quot; + Base64URL(Payload)</code> using a secret or private key.</li></ol><h3 id="the-missing-verification-trap" tabindex="-1">The Missing Verification Trap <a class="header-anchor" href="#the-missing-verification-trap" aria-label="Permalink to &quot;The Missing Verification Trap&quot;">​</a></h3><p>In some vulnerable applications, backend developers use convenience helper functions like <code>jwt.decode()</code> instead of <code>jwt.verify()</code>. When this happens, the server reads the payload claims without checking the cryptographic signature at all, accepting any arbitrary token modifications!</p><p>In other cases, vulnerable libraries accept tokens specifying <code>&quot;alg&quot;: &quot;none&quot;</code>. If an attacker modifies the payload and strips the signature (leaving the trailing dot: <code>header.payload.</code>), the server treats the token as valid.</p>',18)),a(i,{ids:"jwt-lab-jwt-authentication-bypass-via-unverified-signature, jwt-lab-jwt-authentication-bypass-via-flawed-signature-verification"}),e[1]||(e[1]=t('<details class="details custom-block"><summary>🔬 Under the Hood: Why the Spec Allowed <code>alg: none</code></summary><p>The original RFC 7519 specification included <code>&quot;alg&quot;: &quot;none&quot;</code> for situations where token integrity is already guaranteed by an external transport layer (such as an established mutual-TLS tunnel). However, when verification libraries allowed this parameter dynamically, it enabled attackers to turn off cryptographic enforcement with a single string change. Modern libraries reject <code>none</code> by default, but legacy systems and misconfigured options remain common.</p></details><hr><h2 id="weak-signing-keys-and-offline-cracking" tabindex="-1">Weak Signing Keys and Offline Cracking <a class="header-anchor" href="#weak-signing-keys-and-offline-cracking" aria-label="Permalink to &quot;Weak Signing Keys and Offline Cracking&quot;">​</a></h2><p>When tokens use symmetric HMAC signing algorithms (like <strong>HS256</strong>), both signing and verification rely on the exact same shared secret string.</p><p>If the developers chose a weak, guessable secret (such as <code>secret</code>, <code>password123</code>, or the company name), an investigator can take a valid token observed in browser cookies and perform <strong>offline dictionary cracking</strong> using tools like Hashcat. Because the attack runs entirely offline on the tester&#39;s machine, it triggers zero rate limits and leaves zero traces in server logs. Once the secret is found, the investigator can sign arbitrary payloads with full validity.</p>',5)),a(i,{ids:"jwt-lab-jwt-authentication-bypass-via-weak-signing-key"}),e[2]||(e[2]=t('<hr><h2 id="header-injection-jwk-and-jku" tabindex="-1">Header Injection: <code>jwk</code> and <code>jku</code> <a class="header-anchor" href="#header-injection-jwk-and-jku" aria-label="Permalink to &quot;Header Injection: `jwk` and `jku`&quot;">​</a></h2><p>The JSON Web Signature (JWS) specification defines several optional header parameters that describe the public key used for verification:</p><ul><li><strong>Embedded Keys (<code>jwk</code>):</strong> The <code>jwk</code> header parameter allows the token to embed a JSON Web Key object directly inside its own header. If the server trusts this header, an attacker generates their own RSA key pair, embeds their public key in the <code>jwk</code> header, and signs the token with their matching private key!</li><li><strong>Key Set URLs (<code>jku</code>):</strong> The <code>jku</code> header parameter points to a remote URL hosting a JSON Web Key Set. If the server fetches this URL without validating it against an approved whitelist, an attacker points <code>jku</code> to their own server and serves their own public keys.</li></ul>',4)),a(i,{ids:"jwt-lab-jwt-authentication-bypass-via-jwk-header-injection, jwt-lab-jwt-authentication-bypass-via-jku-header-injection"}),e[3]||(e[3]=t('<hr><h2 id="key-id-kid-path-traversal-and-sql-injection" tabindex="-1">Key ID (<code>kid</code>) Path Traversal and SQL Injection <a class="header-anchor" href="#key-id-kid-path-traversal-and-sql-injection" aria-label="Permalink to &quot;Key ID (`kid`) Path Traversal and SQL Injection&quot;">​</a></h2><p>The <code>kid</code> (Key ID) header parameter is an optional identifier that tells the server which key in its keystore to use for verification.</p><p>When backend implementations use the <code>kid</code> value directly inside filesystem path lookups (e.g. <code>open(&quot;/keys/&quot; + header.kid)</code>) or database queries, it introduces classic injection bugs:</p><ul><li><strong>Path Traversal in <code>kid</code>:</strong> Setting <code>kid: &quot;../../../../../dev/null&quot;</code> directs the server to read from <code>/dev/null</code> on Linux systems. Because <code>/dev/null</code> is an empty file, the secret key becomes a zero-length string. Signing the token with an empty secret (<code>&quot;&quot;</code>) results in a valid signature!</li><li><strong>SQL Injection in <code>kid</code>:</strong> If <code>kid</code> is passed to a database query, injecting a SQL UNION payload can force the query to return a known string that the attacker can use to sign the token.</li></ul>',5)),a(i,{ids:"jwt-lab-jwt-authentication-bypass-via-kid-header-path-traversal"}),e[4]||(e[4]=t(`<hr><h2 id="algorithm-confusion-attacks" tabindex="-1">Algorithm Confusion Attacks <a class="header-anchor" href="#algorithm-confusion-attacks" aria-label="Permalink to &quot;Algorithm Confusion Attacks&quot;">​</a></h2><p>Algorithm confusion occurs when an application expects an asymmetric algorithm like <strong>RS256</strong> (which uses a private key to sign and a public key to verify), but the verification library also permits the symmetric algorithm <strong>HS256</strong>.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Normal Asymmetric Flow (RS256):</span></span>
<span class="line"><span>  Sign:   Private Key (Secret on Auth Server)</span></span>
<span class="line"><span>  Verify: Public Key  (Publicly Known Certificate)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Algorithm Confusion Exploit (HS256):</span></span>
<span class="line"><span>  Attacker sets: &quot;alg&quot;: &quot;HS256&quot;</span></span>
<span class="line"><span>  Attacker signs with: Server&#39;s Public Key (which is public!)</span></span>
<span class="line"><span>  Server verifies using: Public Key as the HMAC secret string!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Because HMAC-SHA256 treats whatever key it is given as a symmetric byte string, the server verifies the token using its own public key bytes—and since the attacker signed the token with those exact same public key bytes, the signature passes perfectly!</p>`,5)),a(i,{ids:"jwt-lab-jwt-authentication-bypass-via-algorithm-confusion, jwt-lab-jwt-authentication-bypass-via-algorithm-confusion-with-no-exposed-key"}),e[5]||(e[5]=t('<details class="details custom-block"><summary>⚙️ Engine Variations: How Modern Libraries Prevent JWT Attacks</summary><ul><li><strong>jsonwebtoken (Node.js):</strong> Developers must pass an explicit <code>algorithms: [&#39;RS256&#39;]</code> array option. Omitting this option allows algorithm confusion andPermits the token to dictate the verification routine.</li><li><strong>PyJWT (Python):</strong> Modern versions strictly require the <code>algorithms</code> parameter in <code>jwt.decode()</code> and automatically reject <code>none</code> unless explicitly requested.</li><li><strong>Spring Security (Java):</strong> <code>NimbusJwtDecoder</code> binds the decoder to a specific expected <code>JWSAlgorithm</code>, preventing algorithm confusion at the framework level.</li></ul></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ Core Defensive Checklist:</strong> Always pin the expected verification algorithm server-side. Completely disable support for <code>alg: none</code>. Ensure symmetric HMAC secrets are high-entropy cryptographic strings (minimum 256 bits). When using asymmetric keys (RS256/ES256), strictly enforce asymmetric key types to prevent algorithm confusion, and never trust client-supplied <code>jwk</code>, <code>jku</code>, or raw <code>kid</code> header parameters.</p></div>',2)),a(n,{"topic-id":"jwt",label:"Mark JWT attacks complete"})])}const k=o(d,[["render",l]]);export{f as __pageData,k as default};
